BodyContent.ST:
IF X1 OR X2 THEN
    bRun := FALSE;
    bDelayAck := FALSE;
    nStep := 0;
END_IF;
IF X0 AND NOT bX0Last AND NOT X1 AND NOT X2 THEN
    bRun := TRUE;
    bDelayAck := FALSE;
    nStep := 1;
END_IF;
bX0Last := X0;
CASE nStep OF
    1:
        tStepTime := T#1500ms;
    2:
        tStepTime := T#600ms;
    3:
        tStepTime := T#1500ms;
    4:
        tStepTime := T#2000ms;
    5:
        tStepTime := T#1500ms;
    6:
        tStepTime := T#600ms;
    7:
        tStepTime := T#1500ms;
    8:
        tStepTime := T#2000ms;
ELSE
    tStepTime := T#500ms;
END_CASE;
tStep(IN := bRun AND NOT bDelayAck, PT := tStepTime);
IF tStep.Q THEN
    bDelayAck := TRUE;
    IF nStep >= 8 THEN
        nStep := 0;
        bRun := FALSE;
    ELSE
        nStep := nStep + 1;
    END_IF;
END_IF;
IF NOT tStep.Q THEN
    bDelayAck := FALSE;
END_IF;
Y0 := FALSE;
Y1 := FALSE;
Y2 := FALSE;
Y3 := FALSE;
Y4 := FALSE;
IF bRun THEN
    CASE nStep OF
        1:
            Y0 := TRUE;
        2:
            Y0 := TRUE;
            Y2 := TRUE;
        3:
            Y1 := TRUE;
            Y2 := TRUE;
        4:
            Y2 := TRUE;
            Y3 := TRUE;
        5:
            Y0 := TRUE;
            Y2 := TRUE;
            Y3 := TRUE;
        6:
            Y0 := TRUE;
            Y3 := TRUE;
        7:
            Y1 := TRUE;
            Y3 := TRUE;
        8:
            Y4 := TRUE;
    END_CASE;
END_IF;
